//! The tray icon set. Embedded in the binary and written out at startup as a
//! small icon theme, so the panel can load the icons by name and recolour them.
//! The SVGs are generated by assets/brand/tray-icons.py (state icons) and
//! assets/brand/bus-icons.py (the dashboard's bus tiles).

use crate::status::TrayState;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

